"""Bundled course manuals. Keeps downloads available when assets/ is omitted on GitHub."""
import base64, io, zipfile
from functools import lru_cache
_BUNDLE = ''
@lru_cache(maxsize=1)
def archive():
    return zipfile.ZipFile(io.BytesIO(base64.b64decode(_BUNDLE)))
def asset_bytes(name):
    return archive().read(name)
